"use strict";

// The NEGATIVE control that makes RWF-020 sound rather than merely
// conservative. It carries heritage clauses in the three shapes that do
// NOT end module evaluation, and its later export must therefore REMAIN
// authoritative:
//
//  1. `extends baseFactory()` -- a heritage CALL that returns normally.
//     RWF-020 asks only whether evaluating the call completes; it makes no
//     claim about the returned VALUE, and it must not withdraw authority
//     merely because a call appears in a heritage position.
//  2. `extends null` -- legal, and it evaluates no call at all.
//  3. `class Deferred extends bail() {}` inside a function that nothing
//     calls at module scope -- the whole class definition, heritage
//     included, is deferred until `configure()` runs, which it never does
//     here.
//
// All three are proven in-process in the ground-truth fixture's `c.js`.
function dangerousOp(input) {
  return "danger:" + input;
}

function safeOp(input) {
  return "safe:" + input;
}

function bail() {
  throw new Error("throws only when configure() runs");
}

function baseFactory() {
  return class Base {};
}

function configure() {
  class Deferred extends bail() {}
  return Deferred;
}

if (process.env.FIXTURE_LIB_MODE === "fast") {
  module.exports = dangerousOp;
  class Installed extends baseFactory() {}
  class Rootless extends null {}
  void Installed;
  void Rootless;
}

safeOp.configure = configure;
module.exports = safeOp;
